#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1024
static char main_out[2 * MAX_INPUT];

static void do_escape(const char *src) {
    char *dst = main_out;
    while (*src) {
        switch (*src) {
            case '\\':
                *dst++ = '\\';
                *dst++ = '\\';
                break;
            case '"':
                *dst++ = '\\';
                *dst++ = '"';
                break;
            case '\n':
                *dst++ = '\\';
                *dst++ = 'n';
                break;
            case '\t':
                *dst++ = '\\';
                *dst++ = 't';
                break;
            default:
                *dst++ = *src;
                break;
        }
        ++src;
    }
    *dst = '\0';
}

static void do_unescape(const char *src) {
    char *dst = main_out;
    while (*src) {
        if (*src == '\\' && src[1] != '\0') {
            char nxt = src[1];
            switch (nxt) {
                case '\\':
                    *dst++ = '\\';
                    src += 2;
                    continue;
                case '"':
                    *dst++ = '"';
                    src += 2;
                    continue;
                case 'n':
                    *dst++ = '\n';
                    src += 2;
                    continue;
                case 't':
                    *dst++ = '\t';
                    src += 2;
                    continue;
                default:
                    *dst++ = nxt;
                    src += 2;
                    continue;
            }
        }
        *dst++ = *src++;
    }
    *dst = '\0';
}

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strlen(input) > 0x3FF) {
        puts("INVALID");
        return 0;
    }
    if (strcmp(mode, "escape") == 0) {
        do_escape(input);
    } else if (strcmp(mode, "unescape") == 0) {
        do_unescape(input);
    } else {
        puts("INVALID_MODE");
        return 0;
    }
    puts(main_out);
    return 0;
}
